const data = $input.first().json;

const recommendations = Array.isArray(data.recommendations)
  ? data.recommendations
  : [];

const top3 = recommendations
  .filter(p => p && p.propertyId && p.listingUrl)
  .sort((a, b) =>
    Number(b.matchScore || 0) - Number(a.matchScore || 0)
  )
  .slice(0, 3);

return [{
  json: {
    recipient: {
      userId: data.userId,
      fullName: data.fullName,
      email: data.email
    },
    properties: top3,
    propertiesCount: top3.length
  }
}];

/*
 * MADAR - Weekly Recommendations Email
 * n8n Code Node
 * Mode: Run Once for All Items
 * Language: JavaScript
 */

// ================================
// 1. BRAND SETTINGS
// ================================

const BRAND = {
  name: "مدار",
  tagline: "السكن، من منظور أوسع",
  logo: "https://res.cloudinary.com/tadyisak/image/upload/f_auto,q_auto/madar-logo",
  navy: "#414C6B",
  ivory: "#F3F0EB",
  copper: "#BA9077",
  charcoal: "#29292E",
  white: "#FFFFFF",
  muted: "#74747C",
  border: "#E8E4DE"
};

// Change this to your personal test email.
const recipient = $input.first().json.recipient;
const TEST_EMAIL = recipient.email;

if (!recipient.userId || !TEST_EMAIL) {
  throw new Error("Missing weekly report recipient");
}
// Verified sender in Brevo.
const SENDER_EMAIL = "madarplatform@aol.com";

// ================================
// 2. HELPER FUNCTIONS
// ================================

function escapeHtml(value) {
  return String(value ?? "").replace(
    /[&<>"']/g,
    char => ({
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      '"': "&quot;",
      "'": "&#39;"
    })[char]
  );
}

function formatNumber(value) {
  return new Intl.NumberFormat("ar-SA", {
    numberingSystem: "latn",
    maximumFractionDigits: 0
  }).format(Number(value) || 0);
}

function formatScore(value) {
  const score = Number(value);
  return Number.isFinite(score) ? score.toFixed(1) : "0.0";
}

function safeUrl(value) {
  const url = String(value || "").trim();
  return /^https:\/\//i.test(url) ? escapeHtml(url) : "";
}

// ================================
// 3. GET TOP 3 PROPERTIES
// ================================

const input = $input.first().json.properties || [];
const properties = input
  .filter(p => p && p.propertyId && p.listingUrl)
  .sort((a, b) =>
    Number(b.matchScore || 0) -
    Number(a.matchScore || 0)
  )
  .slice(0, 3);

if (properties.length === 0) {
  throw new Error(
    "No valid property recommendations available."
  );
}

// ================================
// 4. PROPERTY CARDS
// ================================

const propertyCards = properties.map((p, index) => {
  const neighborhood = escapeHtml(p.neighborhood || "غير محدد");
  const city = escapeHtml(p.city || "السعودية");
  const price = formatNumber(p.price);
  const bedrooms = formatNumber(p.bedrooms);
  const area = formatNumber(p.areaSqm);
  const score = formatScore(p.matchScore);

  const image = safeUrl(p.image);
  const listingUrl = safeUrl(p.listingUrl);

  const reason = escapeHtml(
    p.aiReason || "عقار يتناسب مع بعض تفضيلاتك السكنية."
  );

  const tradeOff = p.aiTradeOff
    ? escapeHtml(p.aiTradeOff)
    : "";

  return `
  <tr>
    <td style="padding:0 0 20px 0;">

      <table role="presentation" width="100%"
        cellpadding="0" cellspacing="0"
        style="background:${BRAND.white};
        border:1px solid ${BRAND.border};
        border-collapse:separate;
        border-radius:14px;">

        ${image ? `
        <tr>
          <td align="center" style="padding:12px 12px 0;">
            <img src="${image}"
              alt="عقار في حي ${neighborhood}"
              width="520"
              style="display:block;width:100%;
              max-width:520px;height:auto;
              border-radius:9px;border:0;">
          </td>
        </tr>
        ` : ""}

        <tr>
          <td dir="rtl"
            style="padding:24px;
            text-align:right;
            font-family:Tahoma,Arial,sans-serif;">

            <table role="presentation" width="100%"
              cellpadding="0" cellspacing="0">
              <tr>
                <td align="right"
                  style="color:${BRAND.muted};
                  font-size:12px;padding-bottom:12px;">
                  الاختيار ${index + 1}
                </td>
                <td align="left" dir="ltr"
                  style="padding-bottom:12px;">
                  <span style="
                    background:${BRAND.ivory};
                    color:${BRAND.navy};
                    font-size:12px;
                    font-weight:bold;
                    padding:7px 10px;
                    border-radius:20px;">
                    توافق ${score}%
                  </span>
                </td>
              </tr>
            </table>

            <h2 style="
              margin:0 0 8px;
              font-size:21px;
              line-height:1.6;
              color:${BRAND.charcoal};">
              عقار في حي ${neighborhood}
            </h2>

            <p style="
              margin:0 0 16px;
              font-size:13px;
              color:${BRAND.muted};">
              ${city}
            </p>

            <p style="
              margin:0 0 16px;
              color:${BRAND.navy};
              font-size:25px;
              font-weight:bold;">
              ${price}
              <span style="font-size:14px;">
                ر.س
              </span>
            </p>

            <p style="
              margin:0 0 20px;
              padding:12px;
              background:#F8F7F5;
              border-radius:8px;
              color:${BRAND.charcoal};
              font-size:13px;">
              ${bedrooms} غرف نوم
              &nbsp; | &nbsp;
              ${area} م²
            </p>

            <p style="
              margin:0 0 7px;
              color:${BRAND.copper};
              font-size:13px;
              font-weight:bold;">
              لماذا اخترنا لك هذا العقار؟
            </p>

            <p style="
              margin:0 0 16px;
              color:${BRAND.charcoal};
              line-height:1.9;
              font-size:14px;">
              ${reason}
            </p>

            ${tradeOff ? `
            <p style="
              margin:0 0 20px;
              color:${BRAND.muted};
              font-size:12px;
              line-height:1.9;">
              <strong>نقطة للمقارنة:</strong>
              ${tradeOff}
            </p>
            ` : ""}

            <table role="presentation"
              cellpadding="0" cellspacing="0">
              <tr>
                <td bgcolor="${BRAND.navy}"
                  style="border-radius:8px;
                  text-align:center;">
                  <a href="${listingUrl}"
                    target="_blank"
                    style="display:inline-block;
                    padding:13px 28px;
                    background:${BRAND.navy};
                    color:#FFFFFF;
                    text-decoration:none;
                    font-size:14px;
                    font-weight:bold;
                    border-radius:8px;">
                    عرض تفاصيل العقار
                  </a>
                </td>
              </tr>
            </table>

          </td>
        </tr>
      </table>
    </td>
  </tr>
  `;
}).join("");

// ================================
// 5. EMAIL HTML
// ================================

const htmlContent = `
<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
  <meta charset="UTF-8">
  <meta name="viewport"
    content="width=device-width, initial-scale=1.0">
  <title>تقرير مدار الأسبوعي</title>
</head>

<body dir="rtl" style="
  margin:0;
  padding:0;
  background:${BRAND.ivory};
  font-family:Tahoma,Arial,sans-serif;">

  <div style="display:none;
    max-height:0;overflow:hidden;opacity:0;">
    خيارات سكن تناسب تفضيلاتك، اخترناها لك من مدار.
  </div>

  <table role="presentation" width="100%"
    cellpadding="0" cellspacing="0"
    style="background:${BRAND.ivory};">

    <tr>
      <td align="center" style="padding:30px 12px;">

        <table role="presentation" width="100%"
          cellpadding="0" cellspacing="0"
          style="max-width:600px;">

          <!-- HEADER -->

          <tr>
            <td align="center"
              style="background:${BRAND.white};
              border-radius:18px 18px 0 0;
              padding:28px 20px 24px;
              border-bottom:1px solid ${BRAND.border};">

              <img src="${BRAND.logo}"
                alt="شعار مدار"
                width="90"
                style="display:block;width:90px;
                height:auto;margin:0 auto 12px;
                border:0;">

              <h1 style="
                margin:0;
                font-size:27px;
                color:${BRAND.charcoal};
                font-weight:bold;">
                ${BRAND.name}
              </h1>

              <p style="
                margin:6px 0 0;
                color:${BRAND.muted};
                font-size:12px;">
                ${BRAND.tagline}
              </p>

            </td>
          </tr>

          <!-- INTRODUCTION -->

          <tr>
            <td dir="rtl"
              style="background:${BRAND.white};
              padding:30px 28px 18px;
              text-align:right;">

              <p style="
                margin:0 0 12px;
                color:${BRAND.copper};
                font-size:12px;
                font-weight:bold;">
                من مدار، إليك
              </p>

              <h2 style="
                margin:0 0 15px;
                color:${BRAND.charcoal};
                font-size:27px;
                line-height:1.5;">
                تقريرك الأسبوعي
              </h2>

              <p style="
                margin:0;
                color:${BRAND.muted};
                font-size:15px;
                line-height:2;">
                السكن المناسب ما يعتمد على السعر
                فقط، بل على تفاصيل حياتك اليومية.

                اخترنا لك أبرز ${properties.length}
                عقارات بناءً على تفضيلاتك السكنية،
                وميزانيتك، وتنقلاتك، والخدمات
                المهمة بالنسبة لك.
              </p>

            </td>
          </tr>

          <!-- SECTION LABEL -->

          <tr>
            <td dir="rtl" style="
              background:${BRAND.white};
              padding:15px 28px 0;">

              <p style="
                margin:0 0 18px;
                font-weight:bold;
                font-size:17px;
                color:${BRAND.navy};">
                خيارات تستحق اهتمامك
              </p>

            </td>
          </tr>

          <!-- PROPERTY CARDS -->

          <tr>
            <td style="
              background:${BRAND.white};
              padding:0 20px 16px;">

              <table role="presentation" width="100%"
                cellpadding="0" cellspacing="0">
                ${propertyCards}
              </table>

            </td>
          </tr>

          <!-- CLOSING -->

          <tr>
            <td dir="rtl"
              style="background:${BRAND.white};
              padding:12px 28px 32px;
              text-align:center;">

              <p style="
                margin:0;
                font-size:14px;
                color:${BRAND.charcoal};
                line-height:1.9;">
                خيارات أكثر، وقرار سكن أوضح.
              </p>

              <p style="
                margin:12px 0 0;
                font-size:12px;
                color:${BRAND.muted};
                line-height:1.9;">
                تعتمد هذه التوصيات على المعلومات
                المتاحة وقت إعداد التقرير.
                قد تختلف الأسعار أو حالة توفر العقارات.
              </p>

            </td>
          </tr>

          <!-- FOOTER -->

          <tr>
            <td align="center"
              style="background:#E8E6E2;
              padding:25px 18px;
              border-radius:0 0 18px 18px;">

              <p style="
                margin:0 0 6px;
                color:${BRAND.navy};
                font-size:16px;
                font-weight:bold;">
                مدار
              </p>

              <p style="
                margin:0 0 12px;
                color:${BRAND.muted};
                font-size:12px;">
                السكن، من منظور أوسع
              </p>

              <p style="
                margin:0;
                color:${BRAND.muted};
                font-size:11px;
                line-height:1.8;">
                أُرسلت هذه الرسالة من منصة مدار
                كجزء من خدمة التوصيات السكنية.
              </p>

            </td>
          </tr>

        </table>
      </td>
    </tr>
  </table>

</body>
</html>
`;

// ================================
// 6. BREVO EMAIL PAYLOAD
// ================================

const subject = "مدار | تقريرك الأسبوعي للسكن";

const brevoPayload = {
  sender: {
    name: "Madar | مدار",
    email: SENDER_EMAIL
  },
  to: [
    {
      email: TEST_EMAIL
    }
  ],
  subject: subject,
  htmlContent: htmlContent
};

// Exactly one output = one email.
return [{
  json: {
    subject,
    htmlContent,
    propertiesCount: properties.length,
    brevoPayload
  }
}];
